'use strict';

// MODULES //

var max = require( '@stdlib/math/base/special/max' );
var isInteger = require( '@stdlib/assert/is-integer' ).isPrimitive;
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var validate = require( './validate.js' );


// MAIN //

/**
* Creates a public validation contract around a normalized backend.
* @private
* @param {Function} backend - normalized backend
* @param {Function} [eligible] - native eligibility
* @param {Function} [fallback] - validated fallback
* @returns {Function} public routine
*/
function factory( backend, eligible, fallback ) {
	setReadOnly( dpbequ, 'ndarray', ndarray );
	return dpbequ;

	/**
* Computes diagonal scaling from contiguous band storage.
* @private
* @param {string|integer} order - layout
* @param {string|integer} uplo - triangle
* @param {NonNegativeInteger} N - order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - band storage
* @param {PositiveInteger} LDAB - leading dimension
* @param {Float64Array} S - scaling output
* @param {Float64Array} SCOND - scalar output
* @param {Float64Array} AMAX - scalar output
* @throws {TypeError} invalid selector or storage
* @throws {RangeError} invalid metadata or domain
* @returns {integer} INFO
*/
	function dpbequ( order, uplo, N, KD, AB, LDAB, S, SCOND, AMAX ) {
		var column;
		var u;
		if ( order !== 'row-major' && order !== 'column-major' && order !== 101 && order !== 102 ) {
			throw new TypeError( 'invalid argument. Invalid layout.' );
		}
		u = validate.scalars( uplo, N, KD );
		validate.integer( LDAB );
		column = order === 'column-major' || order === 102;
		if ( LDAB < ((column) ? KD+1 : max(1, N)) ) {
			throw new RangeError( 'invalid argument. Invalid leading dimension.' );
		}
		return ndarray( u, N, KD, AB, (column) ? 1 : LDAB, (column) ? LDAB : 1, 0, S, 1, 0, SCOND, 0, AMAX, 0 );
	}

	/**
* Computes diagonal scaling from signed injective band and output views.
* @private
* @param {string|integer} uplo - triangle
* @param {NonNegativeInteger} N - order
* @param {NonNegativeInteger} KD - bandwidth
* @param {Float64Array} AB - band storage
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - band offset
* @param {Float64Array} S - scaling output
* @param {integer} ss - scaling stride
* @param {integer} os - scaling offset
* @param {Float64Array} SCOND - scalar output
* @param {integer} oc - scalar offset
* @param {Float64Array} AMAX - scalar output
* @param {integer} om - scalar offset
* @throws {TypeError} invalid selector or storage
* @throws {RangeError} invalid metadata or domain
* @returns {integer} INFO
*/
	function ndarray( uplo, N, KD, AB, r, c, o, S, ss, os, SCOND, oc, AMAX, om ) { // eslint-disable-line max-params -- Preserve the adopted fourteen-argument ndarray contract.
		var info;
		var use;
		var u;
		u = validate.scalars( uplo, N, KD );
		validate( u, N, KD, AB, r, c, o, S, ss, os, SCOND, oc, AMAX, om );
		use = (eligible && !eligible(u, N, KD, AB, r, c, o, S, ss, os, SCOND, oc, AMAX, om)) ? fallback : backend;
		info = use( u, N, KD, AB, r, c, o, S, ss, os, SCOND, oc, AMAX, om );
		if ( !isInteger(info) || info < 0 || info > N ) {
			throw new RangeError( 'invalid argument. Private INFO is outside the scalar status domain.' );
		}
		return info;
	}
}


// EXPORTS //

module.exports = factory;
